// Domain layer — depends on nothing
public interface IOrderRepository
{
    Task<Order> GetByIdAsync(int id);
    Task SaveAsync(Order order);
}

// Application/Service layer — depends on the Domain interface, not EF Core
public class OrderService
{
    private readonly IOrderRepository _repo;
    public OrderService(IOrderRepository repo) => _repo = repo;

    public async Task<OrderDto> PlaceOrderAsync(int id)
    {
        var order = await _repo.GetByIdAsync(id);
        order.Confirm(); // business rule lives here, not in the controller
        await _repo.SaveAsync(order);
        return new OrderDto(order.Id, order.Status);
    }
}

// Infrastructure layer — implements the Domain interface with EF Core
public class EfOrderRepository : IOrderRepository
{
    private readonly AppDbContext _db;
    public EfOrderRepository(AppDbContext db) => _db = db;
    public Task<Order> GetByIdAsync(int id) => _db.Orders.FindAsync(id).AsTask();
    public Task SaveAsync(Order order) => _db.SaveChangesAsync();
}

[HttpPost("payments")]
public async Task<IActionResult> Pay([FromHeader(Name = "Idempotency-Key")] Guid key,
                                     PaymentRequest req)
{
    try
    {
        await _db.InsertPaymentRequest(key, req.OrderId, "Processing"); // atomically claim
    }
    catch (SqlException ex) when (ex.Number == 2627) // duplicate key
    {
        var existing = await _db.GetPaymentRequest(key);
        if (existing.Status == "Processing") return Conflict("Payment already in progress");
        return Ok(existing.ResponseJson); // replay the ORIGINAL result -- no double charge
    }

    var result = await _gateway.ChargeAsync(req); // charged exactly once
    await _db.CompletePaymentRequest(key, result);
    return Ok(result);
}

