// CQRS with MediatR -- justified only when read/write shapes genuinely diverge
public record GetOrderSummaryQuery(int OrderId) : IRequest<OrderSummaryDto>;

public class GetOrderSummaryHandler : IRequestHandler<GetOrderSummaryQuery, OrderSummaryDto>
{
    private readonly IDbConnection _db; // fast, denormalized read path, bypasses the write model
    public GetOrderSummaryHandler(IDbConnection db) => _db = db;

    public Task<OrderSummaryDto> Handle(GetOrderSummaryQuery q, CancellationToken ct) =>
        _db.QuerySingleAsync<OrderSummaryDto>(
            "SELECT * FROM OrderSummaryView WHERE OrderId = @OrderId", new { q.OrderId });
}

public class OrderCleanupService : BackgroundService // IHostedService
{
    private readonly IServiceScopeFactory _scopeFactory; // can't inject Scoped directly
    private readonly ILogger<OrderCleanupService> _logger;

    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                using var scope = _scopeFactory.CreateScope();
                var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
                await db.Orders.Where(o => o.Expired).ExecuteDeleteAsync(ct);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Cleanup failed"); // never let it kill the loop
            }
            await Task.Delay(TimeSpan.FromMinutes(30), ct);
        }
    }
}

builder.Services.AddHttpClient<IPaymentClient, PaymentClient>(c =>
{
    c.BaseAddress = new Uri(config["Payment:BaseUrl"]);
    c.Timeout = TimeSpan.FromSeconds(10); // ALWAYS set a timeout
})
.AddTransientHttpErrorPolicy(p => p.WaitAndRetryAsync(3,
    attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)))) // exponential backoff
.AddTransientHttpErrorPolicy(p => p.CircuitBreakerAsync(
    handledEventsAllowedBeforeBreaking: 5,
    durationOfBreak: TimeSpan.FromSeconds(30)));

// Precedence (later wins): appsettings.json -> appsettings.{Environment}.json
// -> User Secrets (dev) -> Environment Variables -> Key Vault -> command line
